insert into question_bank_items (id, stage_id, position, question, hint, answer) values (112, 8, 6, 'אימות מול הרשאה (authn/authz) — איך אתה בודק כל אחד?', 'מי אתה, מול מה מותר לך לעשות.', ARRAY['אימות מוכיח זהות; הרשאה מחליטה מה הזהות רשאית לעשות. הם נכשלים אחרת ודורשים בדיקות שונות.', 'לאימות: אישורים תקינים ולא-תקינים, טוקנים שפגו וזויפו, התנתקות ופקיעת session, ונעילה אחרי כשלים חוזרים.', 'הרשאה היא שם חיים הבאגים האמיתיים: הריצו את אותה בקשה בתפקידים שונים וודאו 403 היכן שצריך לדחות — וקריטית, בדקו גישה אופקית, שבה משתמש A מנסה לקרוא את הרשומה של B לפי id (IDOR). אכפו בצד השרת; הסתרת כפתור אינה הרשאה.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (113, 8, 7, 'איך אתה בודק pagination, מיון וסינון על endpoint של רשימה?', 'גבולות וסכומים הם המקום שבו אלה נשברים.', ARRAY['Pagination: עמוד ראשון ואחרון, תוצאה ריקה, גודל עמוד מעבר לסך הכול, ושהסכומים וקישורי העמודים מסתדרים בלי כפילויות או חורים בין עמודים.', 'מיון: עולה ויורד, שוויונות, ערכי null, ורגישות לאותיות — ושדה מיון לא תקין נדחה ולא מתעלמים ממנו בשקט.', 'סינון: פילטרים משולבים, אין התאמה, וקלטים בסגנון injection. שימו לב לבאג ה-offset הקלאסי שבו הוספת שורה באמצע גלילה מזיזה הכול באחד.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (114, 8, 8, 'מהו race condition, ואיך תבדוק אותו?', 'שתי פעולות, תזמון ביש-מזל, מצב מושחת.', ARRAY['Race הוא כשהתוצאה תלויה בתזמון של פעולות מקבילות — שתי בקשות שקוראות-אז-כותבות את אותה יתרה, ושתיהן רואות את הערך הישן.', 'שחזרו על ידי ירי בקשות מקבילות: קנו את הפריט האחרון במלאי משתי sessions בבת אחת, או שלחו את אותו טופס פעמיים, וודאו שהאינvariant נשמר (המלאי לעולם לא שלילי, הזמנה אחת ולא שתיים).', 'הם לא דטרמיניסטיים, אז הריצו את התרחיש המקבילי פעמים רבות, והשתמשו ב-idempotency keys, נעילה אופטימית או אילוצי ייחודיות כתיקון — ואז בדקו שהתיקון דוחה את המפסיד בצורה נקייה.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (115, 8, 9, 'איך אתה בודק endpoints של העלאת והורדת קבצים?', 'הקבצים הלא-מוצלחים נושאים את הסיכון: גדול מדי, סוג שגוי, זדוני.', ARRAY['מסלול מוצלח קודם: קובץ תקין עולה, נשמר, ויורד חזרה בית-בבית עם content type ושם קובץ נכונים.', 'ואז המרחב השלילי: קבצים גדולים מדי, ריקים, סוגי MIME שגויים או מזויפים, סיומות מסוכנות, ושמות בסגנון path-traversal שמכילים הפניות לתיקיית ההורה כדי לצאת מתיקיית ההעלאה.', 'כסו אבטחה ועמידות: קובץ הרצה מוסווה, zip bomb, והעלאה שנקטעה. וודאו שהמגבלות נאכפות בצד השרת ושהשגיאות נקיות ולא 500.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (116, 8, 10, 'עבור על משפחות קודי ה-HTTP, ואחד שנפוץ להשתמש בו לא נכון.', '2xx בסדר, 3xx הפניה, 4xx באשמתך, 5xx באשמתי.', ARRAY['2xx הצלחה (200, 201 נוצר, 204 ללא תוכן), 3xx הפניה, 4xx שגיאות לקוח (400, 401, 403, 404, 409, 422, 429), 5xx שגיאות שרת (500, 502, 503).', 'הכי מנוצל לרעה הוא 200 לשגיאה — API שמחזיר `{"error": "..."}` עם 200 שובר כל לקוח שסומך על קוד הסטטוס, ומסתיר כשלים מהניטור.', 'גם נפוץ לבלבל: 401 (לא מאומת) מול 403 (מאומת אך לא מורשה), ו-400 מול 422 לבקשה תקינת-מבנה שנכשלת בוולידציה.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (117, 8, 11, 'איך אתה בודק rate limiting ו-throttling?', 'הוכיחו שזה מופעל, מתאפס, ונכשל בבטחה.', ARRAY['שלחו בקשות עד המגבלה וודאו שהן עוברות, ואז שהבאה מחזירה 429 עם כותרת `Retry-After`, ושהמגבלות מתאפסות אחרי החלון.', 'בדקו את ההיקף: האם המגבלה לפי משתמש, לפי IP, או לפי מפתח — והאם זהות שנייה עוקפת אותה? בדקו את הגבול בדיוק בסף, לא רק הרבה מעבר לו.', 'וודאו שזה נכשל בבטחה תחת עומס במקום להתמוטט, ושברסטים לגיטימיים בתוך המכסה אינם נחסמים בטעות.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (118, 8, 12, 'כתוב פונקציה שמוצאת כפילויות ברשימה. איך תבדוק אותה?', 'מעבר אחד עם set — ואז נמקו את הסיבוכיות.', ARRAY['`def duplicates(xs): seen=set(); return {x for x in xs if x in seen or seen.add(x)}` — O(n) זמן, O(n) מקום, מול לולאה מקוננת נאיבית O(n²).', 'אמרו את הפשרה בקול: פתרון ה-set מחליף זיכרון במהירות, ומיון קודם יהיה O(n log n) עם O(1) מקום נוסף אם הזיכרון צר.', 'מקרים: רשימה ריקה, ללא כפילויות, כולם זהים, כמה כפילויות שונות, אלמנטים לא ניתנים ל-hash, וקלט גדול כדי להראות שהסיבוכיות משנה. הוסיפו בדיקת תכונה: כל ערך מוחזר מופיע לפחות פעמיים בקלט.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (119, 8, 13, 'מהי בדיקת חוזה מונחית-צרכן, ומתי משתמשים בה?', 'הצרכן כותב את החוזה; הספק מאמת אותו.', ARRAY['כל צרכן מכריז בדיוק על הצורה שהוא צריך מספק; הספק מריץ את החוזים האלה ב-pipeline שלו ולא יכול לפרוס שינוי ששובר צרכן אמיתי.', 'זה תופס שבירת אינטגרציה בלי סביבת end-to-end איטית ומתנדנדת — מהיר, מבודד, ואומר לכם בדיוק איזה צרכן שברתם.', 'השתמשו בזה למיקרו-שירותים ול-API ציבורי עם לקוחות שנוצרים (כלים כמו Pact). זה מחליף את "העלה הכול ותקווה", ומשתלב עם ולידציית סכימה מול מפרט ה-OpenAPI.']::text[]);